import { TabData } from 'tutts';
export { TabData } from 'tutts';

interface AlphaTexOptions {
    /** `\title` metadata. */
    title?: string;
    /** `\subtitle` metadata. */
    subtitle?: string;
    /** `\tempo` metadata (BPM). 0 is treated as unset (not a valid BPM). */
    tempo?: number;
    /** Default: `data.tuning.length` (the structural ceiling). */
    maxVoices?: number;
    /** Label for the `\tuning (...)` clause. */
    tuningLabel?: string;
}
interface AlphaTexResult {
    /** The complete alphaTex document, ready for alphaTab's AlphaTexImporter. */
    tex: string;
    /** Number of `\voice` blocks emitted (1 for monophonic input). */
    voiceCount: number;
    /**
     * Human-readable notes on anything that could not be notated exactly:
     * duration/tuplet approximations, voice overflow beyond `maxVoices`
     * (truncation or removal), and notes clipped at the final barline.
     * Empty when the output is lossless.
     */
    warnings: string[];
}

declare function toAlphaTex(data: TabData, options?: AlphaTexOptions): AlphaTexResult;

export { type AlphaTexOptions, type AlphaTexResult, toAlphaTex };
